sealed interface Node permits File, Dir {}
record File(long bytes) implements Node {}
record Dir(java.util.List<Node> children) implements Node {}

static long size(Node n) {
    return switch (n) {
        case File f -> f.bytes();
        case Dir d -> { long s = 0; for (Node c : d.children()) s += size(c); yield s; }
    };
}
